reference_solutions.python:
def solve(nums: list[int]) -> int:
    values = set(nums)
    best = 0
    for value in values:
        # Count only from the start of a run, so each run is walked once.
        if value - 1 not in values:
            length = 1
            while value + length in values:
                length += 1
            best = max(best, length)
    return best

