def solve(nums: list[int]) -> int:
    if not nums:
        return 0
    nums = sorted(nums)
    best = current = 1
    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            current += 1
        else:
            current = 1
        best = max(best, current)
    return best

def solve(nums: list[int]) -> int:
    values = set(nums)
    lengths = []
    for value in values:
        if value - 1 not in values:
            length = 1
            while value + length in values:
                length += 1
            lengths.append(length)
    return max(lengths)
